S['CH0711B'] = [
    {'k': 'hook', 'ch': 'Mở đầu', 'moc': True, 'label': 'MBB – Ngân hàng Quân đội', 'cap': ('ĐỌC BÁO CÁO', 'NGÂN HÀNG'), 'cols': (WHITE, GOLD), 'chart': {'sym': 'MBBW', 'tf': 'W', 'weeks': 52, 'circles': [[15, 23.63, 'Đỉnh tuần 9/2: 23,63', 0.6], [38, 17.78, 'Đáy tuần 27/7: 17,78', 1.6], [51, 19.7, '28/10: 19,70', 2.6]]}, 'anh': 'bank headquarters tower', 'say': 'Báo cáo tài chính ngân hàng khác hẳn doanh nghiệp sản xuất. Không có giá vốn, không có hàng tồn kho, thay vào đó là thu nhập lãi, nợ xấu, dự phòng, tiền gửi không kỳ hạn. Nhiều người mới nhìn vào thấy rối và chỉ nhìn lợi nhuận. Trong video này mình giới thiệu bộ khung đọc báo cáo ngân hàng gồm năm tầng: thu nhập lãi thuần, chất lượng tài sản, chi phí dự phòng, nguồn vốn giá rẻ và an toàn vốn. Một ngân hàng thương mại lớn trong bảng quý ba năm hai nghìn không trăm hai mươi sáu được dùng làm ví dụ minh họa. Video thuộc seri Đọc BCTC và áp dụng cho mọi ngân hàng, mọi thời kỳ.'},
    {'k': 'cards', 'ch': 'Chương 1 – Tầng 1: Thu nhập lãi thuần', 'moc': True, 'label': 'Lõi kinh doanh của ngân hàng', 'cap': ('TẦNG 1', 'THU NHẬP LÃI THUẦN'), 'cols': (WHITE, GOLD), 'cards': [('Q3/25', '12.991 tỷ', 'thu nhập lãi thuần'), ('Q2/26', '16.894 tỷ', 'thu nhập lãi thuần'), ('Q3/26', '17.836 tỷ', '+37,3% cùng kỳ')], 'anh': 'bank interest income', 'say': 'Tầng đầu tiên là thu nhập lãi thuần, bằng lãi thu từ cho vay và đầu tư trừ lãi trả cho tiền gửi và vốn vay. Đây là lõi thu nhập của hầu hết ngân hàng. Với ngân hàng ví dụ, thu nhập lãi thuần quý ba năm hai nghìn không trăm hai mươi sáu khoảng mười bảy nghìn tám trăm ba mươi sáu tỷ đồng, tăng ba mươi bảy phẩy ba phần trăm so với cùng kỳ. Chuỗi năm quý từ khoảng mười hai nghìn chín trăm chín mươi tỷ lên mười bốn nghìn năm trăm năm mươi lăm, mười bốn nghìn chín trăm mười ba, mười sáu nghìn tám trăm chín mươi bốn, và mười bảy nghìn tám trăm ba mươi sáu tỷ. Một lõi tăng đều như vậy thường đáng tin hơn lợi nhuận tăng nhờ khoản bất thường.'},
    {'k': 'bars', 'ch': 'Chương 2 – Biên lãi thuần NIM và cách đọc', 'moc': True, 'label': 'Thu nhập lãi thuần theo quý của MBB (tỷ đồng) – nền của NIM', 'cap': ('NIM', 'BIÊN LÃI THUẦN'), 'cols': (WHITE, GOLD), 'bars': [('Q3/25', 12991, BLUE, '12.991'), ('Q4/25', 14555, BLUE, '14.555'), ('Q1/26', 14913, BLUE, '14.913'), ('Q2/26', 16894, GREEN, '16.894'), ('Q3/26', 17836, GREEN, '17.836')], 'anh': 'percentage margin chart', 'say': 'Biên lãi thuần, viết tắt NIM, là thu nhập lãi thuần chia cho tài sản sinh lãi bình quân, cho biết ngân hàng giữ lại bao nhiêu phần trăm từ mỗi đồng tài sản sinh lãi. NIM cao thường do nguồn vốn rẻ và cho vay lãi suất tốt, nhưng cũng đi kèm rủi ro nếu ngân hàng cho vay khách hàng rủi ro cao. NIM tăng hay giảm phụ thuộc lãi suất đầu vào và đầu ra, cơ cấu cho vay và cơ cấu tiền gửi. Trong báo cáo, ngân hàng thường công bố NIM trong thuyết minh hoặc báo cáo thường niên. Mình không dùng số NIM cụ thể ở đây vì cần lấy từ báo cáo gốc; điểm quan trọng là xem xu hướng nhiều quý.'},
    {'k': 'checklist', 'ch': 'Chương 3 – Tầng 2: Chất lượng tài sản và nợ xấu', 'moc': True, 'label': 'Phân loại nợ và tỷ lệ nợ xấu', 'cap': ('TẦNG 2', 'NỢ XẤU'), 'cols': (WHITE, GOLD), 'items': [('Nhóm 1: đủ tiêu chuẩn', GREEN), ('Nhóm 2: cần chú ý', GOLD), ('Nhóm 3–5: nợ xấu', RED), ('Theo dõi số tuyệt đối và tốc độ tăng', GOLD)], 'anh': 'bad loans warning', 'say': 'Tầng thứ hai là chất lượng tài sản. Ngân hàng phân loại nợ thành năm nhóm, từ nhóm một là nợ đủ tiêu chuẩn đến nhóm năm là nợ có khả năng mất vốn. Nợ xấu thường tính từ nhóm ba trở lên. Tỷ lệ nợ xấu là nợ xấu chia tổng dư nợ. Quan trọng hơn con số tại một thời điểm là xu hướng và nợ nhóm hai, tức nợ cần chú ý, vì đây là phần dễ chuyển thành nợ xấu quý sau. Theo báo cáo nửa đầu năm của ngân hàng ví dụ, nợ nhóm năm khoảng tám nghìn bảy trăm bốn mươi bảy tỷ đồng, tăng khoảng ba mươi sáu phần trăm. Mình nêu để minh họa việc theo dõi số tuyệt đối và tốc độ tăng chứ không để kết luận.'},
    {'k': 'cards', 'ch': 'Chương 4 – Tầng 3: Chi phí dự phòng', 'moc': True, 'label': 'Dự phòng là bộ đệm, cũng là chi phí', 'cap': ('TẦNG 3', 'DỰ PHÒNG'), 'cols': (WHITE, GOLD), 'cards': [('Dự phòng nhiều', 'thận trọng', 'lợi nhuận thấp hơn'), ('Dự phòng ít', 'lợi nhuận đẹp', 'bộ đệm mỏng'), ('Tỷ lệ bao phủ', 'dự phòng / nợ xấu', 'bộ đệm dày hay mỏng')], 'anh': 'safety cushion pillow', 'say': 'Tầng thứ ba là chi phí dự phòng rủi ro tín dụng. Ngân hàng trích dự phòng để phòng khi khoản vay không thu hồi được. Chi phí này làm giảm lợi nhuận trong kỳ. Một ngân hàng trích dự phòng nhiều cho thấy họ thận trọng hoặc đang lo nợ xấu tăng; trích ít thì lợi nhuận đẹp hơn nhưng bộ đệm mỏng. Đây là lý do cần đọc lợi nhuận trước dự phòng cạnh lợi nhuận sau dự phòng. Nếu lợi nhuận tăng chủ yếu vì dự phòng giảm, chất lượng tăng trưởng thấp hơn. Chỉ số tỷ lệ bao phủ nợ xấu, bằng dự phòng chia nợ xấu, cho biết bộ đệm dày hay mỏng. Hai ngân hàng cùng lợi nhuận có thể rất khác nhau về rủi ro nếu tỷ lệ bao phủ khác nhau.'},
    {'k': 'bars', 'ch': 'Chương 5 – Lợi nhuận quý của ngân hàng ví dụ', 'moc': True, 'label': 'LNST theo quý (tỷ đồng)', 'cap': ('LỢI NHUẬN', 'SAU TẤT CẢ'), 'cols': (WHITE, GOLD), 'bars': [('Q3/25', 5571, BLUE, '5.571'), ('Q4/25', 8763, BLUE, '8.763'), ('Q1/26', 7516, BLUE, '7.516'), ('Q2/26', 8229, BLUE, '8.229'), ('Q3/26', 8039, GREEN, '8.039')], 'anh': 'bank quarterly results', 'say': 'Với ngân hàng ví dụ, lợi nhuận sau thuế quý ba năm hai nghìn không trăm hai mươi sáu khoảng tám nghìn không trăm ba mươi chín tỷ đồng, tăng bốn mươi bốn phẩy ba phần trăm so với cùng kỳ. Chín tháng đầu năm đạt hơn hai mươi ba nghìn bảy trăm tám mươi bốn tỷ, tăng ba mươi hai phần trăm. Tuy nhiên quý ba thấp hơn quý hai khoảng hai phẩy ba phần trăm, trong khi thu nhập lãi thuần vẫn tăng. Điều đó gợi ý chi phí hoạt động hoặc dự phòng đã tăng. Quý bốn năm trước cao bất thường ở tám nghìn bảy trăm sáu mươi hai tỷ, nên khi so sánh cần chú ý nền. Đọc lợi nhuận cạnh lõi và dự phòng giúp bạn hiểu câu chuyện thực sự.'},
    {'k': 'checklist', 'ch': 'Chương 6 – Tầng 4: Nguồn vốn giá rẻ CASA', 'moc': True, 'label': 'Tiền gửi không kỳ hạn', 'cap': ('TẦNG 4', 'CASA'), 'cols': (WHITE, GOLD), 'items': [('CASA cao: chi phí vốn rẻ', GREEN), ('Lãi suất tăng: ít áp lực huy động hơn', GREEN), ('CASA thấp: biên lãi mỏng hơn', RED), ('Xem xu hướng nhiều quý, so đối thủ', GOLD)], 'anh': 'customers mobile banking', 'say': 'Tầng thứ tư là nguồn vốn. Tiền gửi không kỳ hạn, viết tắt CASA, là tiền trong tài khoản thanh toán và tiết kiệm không kỳ hạn, lãi suất rất thấp. Tỷ lệ CASA cao giúp ngân hàng có chi phí vốn rẻ, và khi lãi suất thị trường tăng, ngân hàng ít phải tăng lãi suất huy động hơn đối thủ. Đây là lợi thế cạnh tranh thường bền, khó bị sao chép, vì nó dựa vào số lượng khách hàng và dịch vụ thanh toán. Ngân hàng có CASA thấp phải huy động bằng tiền gửi kỳ hạn lãi cao hoặc trái phiếu, nên biên lãi mỏng hơn. Khi đọc báo cáo, hãy tìm tỷ lệ CASA qua nhiều quý và so với đối thủ cùng quy mô.'},
    {'k': 'checklist', 'ch': 'Chương 7 – Tầng 5: An toàn vốn và tăng trưởng tín dụng', 'moc': True, 'label': 'CAR và hạn mức tăng trưởng', 'cap': ('TẦNG 5', 'AN TOÀN VỐN'), 'cols': (WHITE, GOLD), 'items': [('CAR cao: nhiều dư địa tăng tín dụng', GREEN), ('CAR sát yêu cầu: có thể phải tăng vốn', RED), ('Hạn mức tín dụng do Ngân hàng Nhà nước giao', GOLD), ('Phát hành thêm: cổ đông bị pha loãng', RED)], 'anh': 'capital strength building', 'say': 'Tầng cuối cùng là an toàn vốn. Tỷ lệ an toàn vốn, viết tắt CAR, đo vốn của ngân hàng so với tài sản có rủi ro, có yêu cầu tối thiểu theo quy định. Ngân hàng tăng tín dụng nhanh cần thêm vốn, nên nếu CAR sát yêu cầu họ có thể phải phát hành cổ phiếu hoặc giữ lại lợi nhuận, làm cổ đông bị pha loãng hoặc nhận ít cổ tức. Ngoài ra Ngân hàng Nhà nước giao hạn mức tăng trưởng tín dụng hằng năm cho từng ngân hàng. Vì vậy một ngân hàng lợi nhuận tốt không nhất thiết có thể tăng trưởng nhanh nếu bị giới hạn bởi vốn hoặc hạn mức. Hãy xem tốc độ tăng tín dụng, mức CAR và kế hoạch tăng vốn cùng nhau.'},
    {'k': 'cards', 'ch': 'Chương 8 – Định giá ngân hàng ví dụ', 'moc': True, 'label': 'P/E, P/B, ROE theo dữ liệu 2/11/2026', 'cap': ('ĐỊNH GIÁ', 'SAU KHI ĐỌC'), 'cols': (WHITE, GOLD), 'cards': [('P/E', '5,97', 'dữ liệu 2/11'), ('P/B', '1,24', 'dữ liệu 2/11'), ('ROE', '21,8%', '4 quý'), ('Cổ tức', '4,4%', 'tỷ suất')], 'anh': 'valuation chart analysis', 'say': 'Sau khi đọc năm tầng, chúng ta mới đặt cạnh chỉ số định giá. Theo dữ liệu hai tháng mười một, ngân hàng ví dụ có P trên E khoảng năm phẩy chín bảy, P trên B một phẩy hai bốn, ROE hai mươi mốt phẩy tám phần trăm và tỷ suất cổ tức bốn phẩy bốn phần trăm. ROE cao nhưng P trên E thấp có thể phản ánh thị trường thận trọng về chất lượng tài sản, tốc độ tăng tín dụng hoặc cơ cấu sở hữu. Thị trường không phải lúc nào cũng đúng hoặc sai, nhưng nó luôn có lý do mà ta cần thử đoán. Việc của nhà phân tích là nhận ra lý do đó và quyết định mình có đồng ý hay không.'},
    {'k': 'checklist', 'ch': 'Chương 9 – Bảng kiểm 8 câu hỏi cho báo cáo ngân hàng', 'moc': True, 'label': '8 câu hỏi', 'cap': ('8 CÂU HỎI', 'CHO NGÂN HÀNG'), 'cols': (WHITE, GOLD), 'items': [('Thu nhập lãi thuần tăng đều?', GOLD), ('NIM, CASA xu hướng?', GOLD), ('Nợ xấu, nợ nhóm 2?', GOLD), ('Bao phủ nợ xấu?', GOLD), ('Lợi nhuận trước/sau dự phòng?', GOLD), ('CAR và tăng trưởng tín dụng?', GOLD)], 'anh': 'eight question list', 'say': 'Mình tóm lại thành tám câu hỏi. Thu nhập lãi thuần có tăng đều không? NIM xu hướng ra sao? Nợ xấu và nợ nhóm hai tăng hay giảm? Tỷ lệ bao phủ nợ xấu bao nhiêu? Lợi nhuận trước dự phòng so với sau dự phòng thế nào? Tỷ lệ CASA có ổn định không? CAR còn dư địa không? Tăng trưởng tín dụng có phù hợp với vốn không? Nếu trả lời được tám câu bằng số liệu thật từ báo cáo, bạn hiểu ngân hàng đó tốt hơn đa số nhà đầu tư chỉ nhìn một dòng lợi nhuận. Và nếu có câu không tìm được số liệu, hãy ghi lại để hỏi lần sau hoặc đọc kỹ thuyết minh.'},
    {'k': 'checklist', 'ch': 'Chương 10 – Những bẫy khi đọc ngân hàng', 'moc': True, 'label': 'Ba bẫy', 'cap': ('3 BẪY', 'KHI ĐỌC NGÂN HÀNG'), 'cols': (WHITE, GOLD), 'items': [('Tăng trưởng trên nền thấp', RED), ('So P/E bỏ qua chất lượng tài sản', RED), ('Nhầm hoàn nhập dự phòng với lợi nhuận lõi', RED), ('Mô hình mỗi ngân hàng mỗi khác', GOLD)], 'anh': 'trap maze', 'say': 'Ba bẫy mình thấy nhiều. Bẫy một, chỉ nhìn tăng trưởng lợi nhuận mà không nhìn nền so sánh, vì một quý nền thấp làm mức tăng phình to. Bẫy hai, so P trên E giữa các ngân hàng mà bỏ qua chất lượng tài sản và cơ cấu sở hữu. Bẫy ba, nhầm hoàn nhập dự phòng với kết quả kinh doanh chính. Ngân hàng cũng khác nhau về mô hình, ngân hàng quốc doanh, ngân hàng cổ phần tư nhân, ngân hàng chuyên cho vay tiêu dùng, nên không có chuẩn chung cho mọi nơi. Đọc nhiều báo cáo của cùng một ngân hàng qua nhiều quý rồi mới so với đối thủ thường cho kết quả đáng tin hơn.'},
    {'k': 'end', 'label': '', 'cap': ('ĐỌC BÁO CÁO', 'NGÂN HÀNG'), 'cols': (WHITE, GOLD), 'say': 'Số liệu của ngân hàng trong video lấy từ báo cáo tài chính quý ba năm hai nghìn không trăm hai mươi sáu và dữ liệu tổng hợp ngày hai tháng mười một, dùng làm ví dụ minh họa cách đọc. Nội dung chia sẻ kiến thức, không phải khuyến nghị mua bán chứng khoán. Bảng so sánh ngân hàng có tại chungkhoanhuynguyen chấm com.'},
]

S['CH0711C'] = [
    {'k': 'hook', 'ch': 'Mở đầu', 'moc': True, 'label': 'DBC – Dabaco (chăn nuôi, thực phẩm)', 'cap': ('TÂM LÝ', 'ĐÁM ĐÔNG'), 'cols': (WHITE, GOLD), 'chart': {'sym': 'DBCW', 'tf': 'W', 'weeks': 52, 'circles': [[14, 26.11, 'Đỉnh tuần 2/2: 26,11', 0.6], [47, 14.9, 'Đáy tuần 28/9: 14,90', 1.6], [51, 15.9, '28/10: 15,90', 2.6]]}, 'anh': 'crowd emotion fear greed', 'say': 'Trong đầu tư, kẻ thù lớn nhất thường không phải thị trường mà là cảm xúc của chính mình. Cùng một cổ phiếu, người mua lúc hưng phấn thấy mình là thiên tài, người bán lúc hoảng loạn thấy mình là kẻ ngốc. Biểu đồ trên là một cổ phiếu chăn nuôi đã giảm khoảng bốn mươi ba phần trăm từ đỉnh tuần đầu tháng hai đến đáy tuần cuối tháng chín năm hai nghìn không trăm hai mươi sáu. Trong video này mình giải thích FOMO là gì, bán tháo hoảng loạn diễn ra thế nào, năm thói quen tự hại hay gặp và cách xây hệ thống để cảm xúc ít chi phối quyết định hơn. Nội dung là kiến thức quản trị tâm lý, không phải khuyến nghị.'},
    {'k': 'cards', 'ch': 'Chương 1 – Hai cảm xúc chi phối thị trường', 'moc': True, 'label': 'Tham lam và sợ hãi', 'cap': ('THAM LAM', 'VÀ SỢ HÃI'), 'cols': (WHITE, GOLD), 'cards': [('Tham lam', 'mua đuổi', 'quên rủi ro'), ('Sợ hãi', 'bán tháo', 'quên giá trị'), ('Né lỗ', 'đau mạnh hơn lãi', 'giữ lệnh sai')], 'anh': 'greed fear scale', 'say': 'Mọi cuộc thảo luận về tâm lý thị trường đều quay về hai cảm xúc: tham lam và sợ hãi. Khi giá tăng và bạn bè lãi, tham lam khiến ta muốn mua thêm, mua đuổi, quên rủi ro. Khi giá giảm và tài khoản đỏ, sợ hãi khiến ta muốn bán ngay, bán ở mức thấp, quên giá trị. Đây là phản ứng sinh học bình thường của con người, không phải điểm yếu của riêng ai. Nghiên cứu hành vi tài chính cho thấy nỗi đau mất tiền thường mạnh hơn niềm vui kiếm tiền cùng số lượng, nên ta có xu hướng né lỗ quá mức. Hiểu điều này không loại bỏ cảm xúc, nhưng giúp bạn nhận ra khi nó đang ra quyết định thay mình.'},
    {'k': 'checklist', 'ch': 'Chương 2 – FOMO: sợ bỏ lỡ', 'moc': True, 'label': 'Dấu hiệu và hậu quả', 'cap': ('FOMO', 'SỢ BỎ LỠ'), 'cols': (WHITE, GOLD), 'items': [('Mua mà chưa hiểu doanh nghiệp', RED), ('Không có mức cắt lỗ', RED), ('Quyết định trong vài phút', RED), ('Giải pháp: tiêu chí viết sẵn, chờ 24 giờ', GREEN)], 'anh': 'chasing trend running', 'say': 'FOMO là nỗi sợ bỏ lỡ cơ hội. Nó xuất hiện khi một cổ phiếu tăng mạnh liên tiếp, mọi người bàn luận, và bạn cảm thấy nếu không mua ngay thì mất cơ hội làm giàu. Dấu hiệu nhận biết là bạn mua mà không biết rõ doanh nghiệp, không có mức cắt lỗ, và quyết định trong vài phút. Hậu quả điển hình là mua ở gần đỉnh của nhịp tăng ngắn, rồi bị kẹt. Cách đối phó gồm ba điều. Luôn có danh sách theo dõi và tiêu chí mua viết sẵn, chỉ mua khi đạt tiêu chí. Đặt quy tắc chờ hai mươi bốn giờ trước khi mua mã bạn mới nghe lần đầu. Nhắc mình rằng thị trường luôn có cơ hội mới, còn vốn đã mất thì khó lấy lại.'},
    {'k': 'bars', 'ch': 'Chương 3 – Bán tháo hoảng loạn và mức giảm có thật', 'moc': True, 'label': 'Mức giảm từ đỉnh tuần đến đáy tuần (%)', 'cap': ('BÁN THÁO', 'Ở ĐÁY'), 'cols': (WHITE, GOLD), 'bars': [('Đỉnh tuần 2/2', 26.11, BLUE, '26,11'), ('Đáy tuần 28/9', 14.9, RED, '14,90'), ('28/10', 15.9, BLUE, '15,90')], 'anh': 'panic selling red screen', 'say': 'Ngược lại với FOMO là bán tháo trong hoảng loạn. Biểu đồ của cổ phiếu chăn nuôi ví dụ cho thấy giá tuần giảm từ khoảng hai mươi sáu nghìn một trăm đồng đầu tháng hai xuống mười bốn nghìn chín trăm đồng cuối tháng chín, tức giảm khoảng bốn mươi ba phần trăm. Tại thời điểm đáy, tin tức thường xấu, người xung quanh nói còn giảm nữa, và áp lực bán là lớn nhất. Cùng thời gian, theo dữ liệu tổng hợp, cổ phiếu này có P trên B khoảng không phẩy bảy sáu, tức giá thấp hơn giá trị sổ sách. Nhưng giá dưới sổ sách không có nghĩa là đáy, nó chỉ là một dữ kiện cần thêm phân tích, và mình không dùng nó để đưa ra kết luận về doanh nghiệp.'},
    {'k': 'checklist', 'ch': 'Chương 4 – Năm thói quen tự hại', 'moc': True, 'label': 'Những thói quen lặp lại', 'cap': ('5 THÓI QUEN', 'TỰ HẠI'), 'cols': (WHITE, GOLD), 'items': [('Nhìn giá liên tục', RED), ('Bàn luận trong nhóm kín cùng quan điểm', RED), ('Chỉ tìm tin xác nhận quan điểm', RED), ('Bình quân giá xuống theo cảm xúc', RED), ('So sánh kết quả với người khác', RED)], 'anh': 'bad habits phone checking', 'say': 'Năm thói quen tự hại. Một, kiểm tra giá liên tục trong ngày, mỗi lần nhìn là một lần cảm xúc dao động. Hai, bàn luận quá nhiều trong nhóm kín, nơi mọi người củng cố niềm tin của nhau. Ba, tìm tin xác nhận quan điểm sẵn có và bỏ qua tin trái chiều. Bốn, bình quân giá xuống theo cảm xúc mà không có kế hoạch. Năm, so sánh với người khác, thấy người ta lãi hơn thì bỏ kế hoạch của mình để chạy theo. Mỗi thói quen đều bắt nguồn từ nhu cầu tự nhiên, an tâm, thuộc về cộng đồng, và được công nhận, nhưng chúng đưa bạn xa khỏi kế hoạch. Nhận ra một vài thói quen ở chính mình là bước đầu tiên để thay đổi.'},
    {'k': 'cards', 'ch': 'Chương 5 – Thiên kiến xác nhận', 'moc': True, 'label': 'Chúng ta thấy điều chúng ta muốn thấy', 'cap': ('THIÊN KIẾN', 'XÁC NHẬN'), 'cols': (WHITE, GOLD), 'cards': [('Đã mua', 'chỉ đọc bài khen', 'bỏ qua cảnh báo'), ('Cách chữa', 'viết 3 lý do thất bại', 'trước khi mua'), ('Định kỳ', 'đọc lại', 'xem lý do nào thành hiện thực')], 'anh': 'mirror confirm belief', 'say': 'Thiên kiến xác nhận là xu hướng tìm và tin những thông tin ủng hộ điều mình đã tin, và bỏ qua điều trái ngược. Khi bạn đã mua một cổ phiếu, bạn sẽ chú ý bài viết khen và coi nhẹ bài viết cảnh báo. Cách đối phó thực tế là chủ động tìm lập luận phản bác. Trước khi mua, hãy viết ra ba lý do doanh nghiệp có thể thất bại, và sau khi mua, định kỳ đọc lại. Nếu một lý do trở thành hiện thực, đó là tín hiệu xem xét lại. Nếu bạn không viết ra nổi ba lý do thất bại, có lẽ bạn chưa hiểu đủ doanh nghiệp. Người đầu tư giỏi không phải người luôn đúng mà là người thường xuyên tự hỏi mình đang sai ở đâu.'},
    {'k': 'checklist', 'ch': 'Chương 6 – Hiệu ứng bầy đàn và nhóm chat', 'moc': True, 'label': 'Khi cả nhóm cùng nghĩ một cách', 'cap': ('BẦY ĐÀN', 'VÀ NHÓM CHAT'), 'cols': (WHITE, GOLD), 'items': [('Đa số trong nhóm nhỏ ≠ thị trường', GOLD), ('Người nói mạnh không chịu trách nhiệm', RED), ('Dùng nhóm để tìm ý tưởng', GREEN), ('Tự kiểm tra bằng báo cáo trước khi hành động', GREEN)], 'anh': 'group chat discussion', 'say': 'Bầy đàn là xu hướng làm theo đa số vì cho rằng đa số hiểu biết hơn. Trong nhóm chat, cảm giác này mạnh hơn vì mọi người cùng chia sẻ một câu chuyện và hiếm ai muốn là người nghi ngờ. Điều cần nhớ là đa số trong một nhóm nhỏ không đại diện cho thị trường, và nhiều người đưa ý kiến mạnh mẽ không chịu trách nhiệm nếu bạn thua lỗ. Mình khuyên bạn không từ bỏ cộng đồng, vì học hỏi lẫn nhau rất có giá trị, nhưng hãy tách ý tưởng ra khỏi quyết định. Dùng nhóm để tìm ý tưởng, rồi tự kiểm tra bằng báo cáo tài chính và kế hoạch rủi ro của mình trước khi hành động.'},
    {'k': 'checklist', 'ch': 'Chương 7 – Xây hệ thống để cảm xúc ít can thiệp', 'moc': True, 'label': 'Năm công cụ', 'cap': ('5 CÔNG CỤ', 'CHỐNG CẢM XÚC'), 'cols': (WHITE, GOLD), 'items': [('1. Kế hoạch giao dịch viết sẵn', GOLD), ('2. Nhật ký quyết định', GOLD), ('3. Đặt lệnh trước', GOLD), ('4. Giới hạn số lần xem giá', GOLD), ('5. Chỉ dùng tiền nhàn rỗi', GOLD)], 'anh': 'system process checklist', 'say': 'Cảm xúc không biến mất, nhưng bạn có thể giảm tác động của nó bằng hệ thống. Công cụ một, kế hoạch giao dịch viết sẵn: điều kiện vào, mức cắt lỗ, tỷ trọng. Công cụ hai, nhật ký quyết định ghi lý do, cảm xúc và kết quả. Công cụ ba, đặt lệnh trước thay vì quyết định lúc thị trường biến động mạnh. Công cụ bốn, giới hạn tần suất xem giá, ví dụ chỉ một lần mỗi ngày. Công cụ năm, dùng tiền nhàn rỗi, vì tiền cần dùng khiến mọi biến động giá trở thành nỗi lo. Khi hệ thống đứng giữa cảm xúc và hành động, bạn có thêm khoảng thời gian để suy nghĩ, và khoảng đó thường tạo khác biệt lớn nhất.'},
    {'k': 'checklist', 'ch': 'Chương 8 – Khi thị trường rung lắc: quy trình 4 bước', 'moc': True, 'label': 'Bốn bước', 'cap': ('4 BƯỚC', 'KHI THỊ TRƯỜNG RUNG'), 'cols': (WHITE, GOLD), 'items': [('1. Dừng lại ít nhất một giờ', GOLD), ('2. Mở kế hoạch đã viết', GOLD), ('3. Báo cáo tài chính có đổi không?', GOLD), ('4. Hành động nhỏ, có thể hoàn tác', GOLD)], 'anh': 'calm breathing pause', 'say': 'Khi thị trường giảm mạnh và bạn thấy bồn chồn, hãy làm bốn việc theo thứ tự. Một, dừng lại, không hành động trong ít nhất một giờ. Hai, mở kế hoạch đã viết và xem tình huống hiện tại có nằm trong kịch bản đã lường trước không. Ba, hỏi báo cáo tài chính của doanh nghiệp có thay đổi gì không, hay chỉ giá thay đổi. Bốn, nếu có hành động, chọn hành động nhỏ và có thể hoàn tác, thay vì bán hết hoặc mua hết. Quy trình đơn giản này giúp tách phản ứng sinh học ra khỏi quyết định đầu tư, và theo kinh nghiệm của nhiều người, đa số những hối tiếc lớn nhất đến từ những quyết định đưa ra trong vòng vài phút đầu của một biến động.'},
    {'k': 'cards', 'ch': 'Chương 8b – Neo giá và hiệu ứng ngưỡng', 'moc': True, 'label': 'Vì sao ta cứ nhớ giá mua hoặc giá đỉnh', 'cap': ('NEO GIÁ', 'GIÁ MUA, GIÁ ĐỈNH'), 'cols': (WHITE, GOLD), 'cards': [('Neo giá', 'bám giá mua/đỉnh', 'thị trường không biết'), ('Câu hỏi thử', 'nếu đang giữ tiền mặt', 'có mua mã này không?'), ('Hiệu ứng sở hữu', 'đánh giá cao đồ mình có', 'khó bán mã lỗ')], 'anh': 'anchor ship harbor', 'say': 'Hai thiên kiến cuối cùng nên biết. Neo giá: ta bám vào một con số, thường là giá mua hoặc giá đỉnh, và dùng nó làm thước đo cho mọi quyết định. Cổ phiếu từng ở hai mươi sáu nghìn nên bây giờ mười lăm nghìn là rẻ, dù doanh nghiệp đã thay đổi. Thị trường không biết và không quan tâm giá bạn mua. Khi đánh giá một khoản đầu tư, hãy tự hỏi nếu hôm nay tôi đang giữ tiền mặt, tôi có mua mã này ở mức giá này không? Nếu câu trả lời là không, bạn đang giữ vì neo giá. Thiên kiến thứ hai là hiệu ứng sở hữu: ta đánh giá món đồ mình có cao hơn giá thực của nó. Hai thiên kiến này giải thích vì sao ta khó bán mã lỗ và khó chấp nhận mã khác tốt hơn.'},
    {'k': 'checklist', 'ch': 'Chương 9 – Tâm lý người thắng và người thua dài hạn', 'moc': True, 'label': 'Khác biệt cốt lõi', 'cap': ('KHÁC BIỆT', 'DÀI HẠN'), 'cols': (WHITE, GOLD), 'items': [('Thị trường là cuộc chơi nhiều năm', GREEN), ('Chấp nhận chuỗi thua, thua nhỏ', GREEN), ('Không đổi phương pháp sau mỗi cú thua', GREEN), ('Mỗi lệnh không phải bài kiểm tra bản thân', GOLD)], 'anh': 'marathon runner long distance', 'say': 'Khác biệt giữa người bền bỉ và người bỏ cuộc thường không nằm ở trí thông minh. Người bền bỉ nhìn thị trường như một cuộc chơi nhiều năm, chấp nhận chuỗi thua, thua nhỏ và thắng vừa đủ. Người bỏ cuộc nhìn từng lệnh như bài kiểm tra giá trị bản thân, nên mỗi lần thua đều đau và mỗi lần thắng đều làm tăng liều. Họ cũng hay thay đổi phương pháp liên tục sau mỗi cú thua, nên không bao giờ có đủ dữ liệu để biết phương pháp có hiệu quả không. Nếu bạn chọn một phương pháp hợp lý, giới hạn rủi ro và tuân thủ trong nhiều năm, bạn đã vượt qua đa số người tham gia thị trường.'},
    {'k': 'end', 'label': '', 'cap': ('TÂM LÝ', 'LÀ KỶ LUẬT'), 'cols': (WHITE, GOLD), 'say': 'Mức giảm của cổ phiếu trong video tính từ đỉnh tuần đến đáy tuần theo nến tuần đến ngày hai mươi tám tháng mười năm hai nghìn không trăm hai mươi sáu, chỉ số P trên B lấy từ dữ liệu tổng hợp ngày hai tháng mười một. Nội dung chia sẻ kiến thức, không phải khuyến nghị mua bán chứng khoán. Xem thêm tại chungkhoanhuynguyen chấm com.'},
]
